import java.util.*;

class Solution {
  public int sumOfPowers(int[] nums, int k) {
    Arrays.sort(nums);
    final int MOD = 1_000_000_007;
    TreeSet<Integer> gaps = new TreeSet<>();
    for (int i = 0; i < nums.length; i++)
      for (int j = i + 1; j < nums.length; j++) gaps.add(nums[j] - nums[i]);
    long answer = 0;
    int previous = 0;
    for (int gap : gaps) {
      answer = (answer + (long) (gap - previous) * countAtLeastGap(nums, k, gap, MOD)) % MOD;
      previous = gap;
    }
    return (int) answer;
  }

  private long countAtLeastGap(int[] nums, int k, int gap, int mod) {
    int n = nums.length;
    long[][] prefix = new long[k + 1][n + 1];
    for (int i = 0; i < n; i++) {
      int firstAllowed = 0;
      while (firstAllowed < i && nums[firstAllowed] <= nums[i] - gap) firstAllowed++;
      for (int size = 1; size <= k; size++) {
        long ways = size == 1 ? 1 : prefix[size - 1][firstAllowed];
        prefix[size][i + 1] = (prefix[size][i] + ways) % mod;
      }
    }
    return prefix[k][n];
  }
}
